class DiscountStrategy:
    FIDELITY_THRESHOLD = 1000
    BULK_QUANTITY_THRESHOLD = 20
    BULK_DISCOUNT_RATE = 0.1
    LARGE_ORDER_DISCOUNT_RATE = 0.07
    FIDELITY_DISCOUNT_RATE = 0.05
    LARGE_ORDER_ITEM_THRESHOLD = 10

    def __init__(self, customer, cart, promotion=None):
        self.customer = customer
        self.cart = cart
        self.promotion = promotion
        self.__total = self._calculate_total()

    def _calculate_total(self):
        return sum(item['quantity'] * item['price'] for item in self.cart)

    def total(self):
        return self.__total

    def due(self):
        discount = self._get_discount()
        return self.__total - discount

    def _get_discount(self):
        if self.promotion is None:
            return 0
        return self.promotion(self)

    @staticmethod
    def FidelityPromo(order):
        return order.total() * DiscountStrategy.FIDELITY_DISCOUNT_RATE if order.customer['fidelity'] >= DiscountStrategy.FIDELITY_THRESHOLD else 0

    @staticmethod
    def BulkItemPromo(order):
        return sum(
            item['quantity'] * item['price'] * DiscountStrategy.BULK_DISCOUNT_RATE
            for item in order.cart
            if item['quantity'] >= DiscountStrategy.BULK_QUANTITY_THRESHOLD
        )

    @staticmethod
    def LargeOrderPromo(order):
        unique_products = {item['product'] for item in order.cart}
        return order.total() * DiscountStrategy.LARGE_ORDER_DISCOUNT_RATE if len(unique_products) >= DiscountStrategy.LARGE_ORDER_ITEM_THRESHOLD else 0
